function ensureFoodDiscounts(){if(state.foodDiscountDay!==state.dayOfMonth){state.foodDiscountDay=state.dayOfMonth;state.foodDiscounts={};yemekseleItems.forEach(it=>{if(Math.random()<0.20){state.foodDiscounts[it.id]=0.15+Math.random()*0.15}})}}
function getFoodDiscount(it){return state.foodDiscounts&&state.foodDiscounts[it.id]}
function getFoodPrice(it){const d=getFoodDiscount(it);if(!d)return it.price;return Math.round(it.price*(1-d)/10)*10}
