const nextDay=d=>{const days=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];const i=days.indexOf(d);return i>=0?days[(i+1)%7]:'Pzt'};
const dayFullNames={Pzt:'Pazartesi',Sal:'Salı',Çar:'Çarşamba',Per:'Perşembe',Cum:'Cuma',Cmt:'Cumartesi',Paz:'Pazar'};
const monthBoundaries=[
{month:9,name:'Eylül',startDay:1,endDay:30},
{month:10,name:'Ekim',startDay:31,endDay:61},
{month:11,name:'Kasım',startDay:62,endDay:91},
{month:12,name:'Aralık',startDay:92,endDay:122},
{month:1,name:'Ocak',startDay:123,endDay:153},
{month:2,name:'Şubat',startDay:154,endDay:181},
{month:3,name:'Mart',startDay:182,endDay:212},
{month:4,name:'Nisan',startDay:213,endDay:242},
{month:5,name:'Mayıs',startDay:243,endDay:273},
{month:6,name:'Haziran',startDay:274,endDay:303},
{month:7,name:'Temmuz',startDay:304,endDay:334},
{month:8,name:'Ağustos',startDay:335,endDay:365}
];
function getCalDate(d){const m=monthBoundaries.find(x=>d>=x.startDay&&d<=x.endDay)||monthBoundaries[0];return{day:d-m.startDay+1,month:m.month,monthName:m.name}}
function dayCounterFor(month,day){const m=monthBoundaries.find(x=>x.month===month);return m?m.startDay+day-1:0}
function fmtExamDate(d){if(!d)return'-';const m=monthBoundaries.find(x=>x.month===d.month);return d.day+' '+(m?m.name:'')}
function daysUntilDate(d){if(!d)return 999;return dayCounterFor(d.month,d.day)-state.dayOfMonth}
function matchesDate(d){if(!d)return false;const cal=getCalDate(state.dayOfMonth);return cal.month===d.month&&cal.day===d.day}
function getCurrentSemester(){const cal=getCalDate(state.dayOfMonth);if(cal.month>=10||cal.month<=1)return'guz';if(cal.month>=2&&cal.month<=6)return'bahar';return'yaz'}
function getDayOfWeek(d){const names=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];return names[((d-20)%7+7)%7]}
